<?php
declare(strict_types=1);
require_once __DIR__.'/../app/helpers/auth.php';
require_once __DIR__.'/../app/config/database.php';
require_once __DIR__.'/../app/helpers/erp_oc_recepciones.php';
requireLogin();$acceso=erpr_acceso(currentUser()?:[]);
$ocId=(int)($_GET['oc']??0);$recId=(int)($_GET['rec']??0);$ocs=[];$recibos=[];$buenas=[];$incidencias=[];$detalles=[];$error='';$oc=null;
try{
 $db=(new Database())->connect();
 if($recId>0){$q=$db->prepare('SELECT orden_id FROM erp_oc_recepciones WHERE id=?');$q->execute([$recId]);$ocId=(int)$q->fetchColumn();}
 if($ocId<1)throw new RuntimeException('Selecciona una orden desde Recepciones pendientes.');
 $q=$db->prepare('SELECT o.id,o.folio,o.destino,o.estado,p.nombre proveedor FROM erp_ordenes_compra o JOIN proveedores p ON p.id=o.proveedor_id WHERE o.id=?');$q->execute([$ocId]);$oc=$q->fetch(PDO::FETCH_ASSOC)?:null;
 if(!$oc){http_response_code(404);exit('Orden no encontrada.');}
 if(!erpr_puede_ver_destino($acceso,(string)$oc['destino'])){http_response_code(403);exit('No puedes consultar este destino.');}
 $detalles=erpr_detalles($db,$ocId);
 $q=$db->prepare('SELECT r.*,u.nombre receptor FROM erp_oc_recepciones r LEFT JOIN usuarios u ON u.id=r.usuario_id WHERE r.orden_id=? ORDER BY r.id DESC');$q->execute([$ocId]);$recibos=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare('SELECT d.recepcion_id,d.cantidad_piezas,d.lote,d.caducidad,od.codigo_snapshot,od.descripcion_snapshot FROM erp_oc_recepciones_detalle d JOIN erp_ordenes_compra_detalle od ON od.id=d.orden_detalle_id JOIN erp_oc_recepciones r ON r.id=d.recepcion_id WHERE r.orden_id=? ORDER BY d.id');$q->execute([$ocId]);
 foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$buenas[(int)$r['recepcion_id']][]=$r;
 $q=$db->prepare('SELECT i.*,od.codigo_snapshot,od.descripcion_snapshot FROM erp_oc_recepcion_incidencias i LEFT JOIN erp_ordenes_compra_detalle od ON od.id=i.orden_detalle_id JOIN erp_oc_recepciones r ON r.id=i.recepcion_id WHERE r.orden_id=? ORDER BY i.id');$q->execute([$ocId]);
 foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r)$incidencias[(int)$r['recepcion_id']][]=$r;
}catch(Throwable $e){error_log('Historial calidad: '.$e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'No se puede consultar el historial. Comprueba que instalaste el parche de calidad.';}
$e=static fn(mixed $v):string=>erpr_html($v);$s=0;$b=0;foreach($detalles as $d){$s+=(int)$d['solicitadas'];$b+=(int)$d['recibidas'];}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>G&D · Entregas parciales e incidencias</title><style>body{margin:0;font:14px system-ui,sans-serif;background:#eff4fa;color:#183b5e}header{padding:22px max(15px,calc((100% - 1180px)/2));background:#123f6e;color:white}header a{color:white}main{max-width:1180px;margin:18px auto;padding:0 14px}.card{background:white;border-radius:12px;padding:18px;margin:14px 0;border:1px solid #dfe9f4}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric{background:#ecf4fc;padding:13px;border-radius:10px}.metric strong{font-size:24px;display:block}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:780px}td,th{padding:10px;border-bottom:1px solid #dce7f3;text-align:left;font-size:13px}th{background:#164a7e;color:white}.btn{display:inline-block;background:#155a99;color:white;text-decoration:none;border-radius:8px;padding:10px;margin:3px 6px 3px 0;font-weight:700}.warn{background:#fff4dd;padding:12px;border:1px solid #e3cea6;border-radius:8px}.ok{background:#e2f4e8;padding:12px;border-radius:8px}.red{color:#b62838}.muted{color:#687c91}.block{border:1px solid #d5e3ef;border-radius:10px;padding:13px;margin:12px 0}h1{margin:0 0 8px;font-size:22px}h2{font-size:18px;margin:0 0 8px}h3{font-size:15px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><header><h1>G&D · Entregas parciales e incidencias</h1><a href="erp_recepciones_pendientes.php">← Pendientes de recepción</a></header><main>
<?php if(isset($_GET['ok'])):?><div class="ok">Entrega registrada con folio independiente. Las piezas malas o sobrantes no se agregaron al inventario.</div><?php endif;?>
<?php if($error):?><div class="warn" role="alert"><?=$e($error)?></div><?php endif;?>
<?php if($oc):?><section class="card"><h2><?=$e($oc['folio'])?> · <?=$e($oc['proveedor'])?></h2><p><?=$e(erpr_destinos()[$oc['destino']]??$oc['destino'])?> · <?=$e($oc['estado'])?></p><div class="grid"><div class="metric"><strong><?=number_format($s)?></strong>Solicitadas</div><div class="metric"><strong><?=number_format($b)?></strong>Buenas recibidas acumuladas</div><div class="metric"><strong><?=number_format(max(0,$s-$b))?></strong>Aún pendientes de buenas</div></div><p class="warn"><b>Importante:</b> «Faltante reportado» y «Dañada» son hechos históricos de una entrega, no sumandos del inventario. Las piezas buenas recibidas después se registran con otro folio. El saldo actual depende de buenas acumuladas, no de sumar incidentes pasados.</p>
<?php if(erpr_puede_registrar_destino($acceso,(string)$oc['destino'])):?><a class="btn" href="erp_recepcion_registrar.php?id=<?=$ocId?>">Registrar nueva entrega / complemento</a><?php endif;?><a class="btn" href="erp_conciliacion_integral.php?oc=<?=$ocId?>">Centro de conciliación</a></section>
<section class="card"><h2>Avance por producto</h2><div class="scroll"><table><thead><tr><th>Código</th><th>Descripción</th><th>Solicitadas</th><th>Buenas acumuladas</th><th>Aún faltan buenas</th></tr></thead><tbody><?php foreach($detalles as $d):$pend=max(0,(int)$d['solicitadas']-(int)$d['recibidas']);?><tr><td><?=$e($d['codigo_snapshot'])?></td><td><?=$e($d['descripcion_snapshot'])?></td><td><?=(int)$d['solicitadas']?></td><td><?=(int)$d['recibidas']?></td><td><?=$pend>0?'<b class="red">'.$pend.'</b>':'0'?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Historial de entregas y comprobantes</h2><?php if(!$recibos):?><p class="muted">Sin entregas registradas para esta OC.</p><?php endif;?>
<?php foreach($recibos as $r):$rid=(int)$r['id'];$buenasRec=$buenas[$rid]??[];$incRec=$incidencias[$rid]??[];$cuenta=0;foreach($buenasRec as $it)$cuenta+=(int)$it['cantidad_piezas'];?><section class="block" <?=$recId===$rid?'style="border:2px solid #2b74ba"':''?>><h3><?=$e($r['folio'])?> · <?=$e($r['fecha_recepcion'])?> · <?=$e($r['estado'])?></h3><p><b>Capturó:</b> <?=$e($r['receptor']??'Usuario')?> · <b>Referencia:</b> <?=$e($r['referencia_factura']?:'Sin referencia')?> · <b>Piezas buenas:</b> <?=number_format($cuenta)?></p><p class="muted"><?=$e($r['observaciones']?:'Sin observaciones generales')?></p>
<?php if($buenasRec):?><div class="scroll"><table><thead><tr><th>Producto</th><th>Buenas</th><th>Lote</th><th>Caducidad</th></tr></thead><tbody><?php foreach($buenasRec as $it):?><tr><td><?=$e($it['codigo_snapshot'].' · '.$it['descripcion_snapshot'])?></td><td><?=number_format((int)$it['cantidad_piezas'])?></td><td><?=$e($it['lote']??'')?></td><td><?=$e($it['caducidad']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php if($incRec):?><h3>Incidencias reportadas en esta entrega</h3><div class="scroll"><table><thead><tr><th>Producto</th><th>Tipo</th><th>Piezas</th><th>Comentario</th></tr></thead><tbody><?php foreach($incRec as $it):?><tr><td><?=$e(($it['codigo_snapshot']??$it['codigo_reportado']??'Sin código').' · '.($it['descripcion_snapshot']??$it['descripcion_reportada']??''))?></td><td><?=$e($it['tipo'])?></td><td><?=number_format((int)$it['cantidad_piezas'])?></td><td><?=$e($it['observaciones'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php if($cuenta>0 && (string)$r['estado']==='REGISTRADA' && in_array((string)$r['destino'],['HIDALGO_BODEGA','TUXTLA_BODEGA'],true) && erpr_puede_registrar_destino($acceso,(string)$r['destino'])):?><a class="btn" href="entradas.php?oc_recepcion=<?=$rid?>">Preparar Entrada de Almacén (solo buenas)</a><?php endif;?>
<a class="btn" href="erp_recepciones_historial.php?ver=<?=$rid?>">Comprobante original REC</a></section><?php endforeach;?></section><?php endif;?></main></body></html>
